{"security_risk":"LOW","summary":"Validate each BibTeX entry via DOI/URL/Crossref search", "command":"python3 - <<'PY'
import re, json, time
from difflib import SequenceMatcher
import requests
import bibtexparser
from bibtexparser.bparser import BibTexParser
from bibtexparser.customization import convert_to_unicode

headers={'User-Agent':'Mozilla/5.0 (OpenHands bibliography integrity checker)'}

# simple latex/braces cleaner for titles
latex_cmd = re.compile(r"\\[a-zA-Z]+\*?(?:\[[^\]]*\])?(?:\{[^{}]*\})?")
brace = re.compile(r"[{}]")

# a few latex escapes that occur in titles
repls = {
    r"\\&": "&",
    r"\\%": "%",
    r"\\_": "_",
    r"\\#": "#",
    r"\\$": "$",
    r"\\textbackslash": "\\",
}

def clean_title(t):
    if not t:
        return t
    for k,v in repls.items():
        t = t.replace(k,v)
    # remove simple latex commands like \emph{...}
    t = re.sub(r"\\[a-zA-Z]+\s*", "", t)
    t = brace.sub('', t)
    t = re.sub(r"\s+", " ", t).strip()
    return t

def doi_resolves(doi):
    if not doi:
        return False, None
    doi = doi.strip().strip('{}').strip()
    url = 'https://doi.org/' + doi
    try:
        r = requests.get(url, headers=headers, timeout=20, allow_redirects=True)
        if r.status_code >= 400:
            return False, r.status_code
        return True, r.status_code
    except Exception as e:
        return False, repr(e)

def url_ok(url):
    if not url:
        return False, None
    try:
        r = requests.get(url, headers=headers, timeout=20, allow_redirects=True)
        return r.status_code < 400, r.status_code
    except Exception as e:
        return False, repr(e)

def crossref_title_exists(title, year=None):
    if not title:
        return False, None
    q = title
    params={'query.title': q, 'rows': 5}
    try:
        r = requests.get('https://api.crossref.org/works', params=params, headers=headers, timeout=25)
        if r.status_code != 200:
            return False, r.status_code
        data = r.json()
        items = data.get('message', {}).get('items', [])
        best = None
        best_score = 0.0
        for it in items:
            tlist = it.get('title') or []
            if not tlist: continue
            t0 = tlist[0]
            score = SequenceMatcher(None, title.lower(), t0.lower()).ratio()
            # small boost if year matches
            it_year = None
            if it.get('issued', {}).get('date-parts'):
                it_year = it['issued']['date-parts'][0][0]
            if year and it_year and str(it_year)==str(year):
                score += 0.05
            if score > best_score:
                best_score = score
                best = {'matched_title': t0, 'score': score, 'doi': it.get('DOI'), 'year': it_year}
        # threshold tuned to avoid false positives
        if best_score >= 0.88:
            return True, best
        return False, best
    except Exception as e:
        return False, repr(e)

bib_text=open('/root/test.bib','r',encoding='utf-8').read()
parser = BibTexParser(common_strings=True)
parser.customization = convert_to_unicode
bib_db = bibtexparser.loads(bib_text, parser=parser)

results=[]
for ent in bib_db.entries:
    title_raw = ent.get('title','')
    title = clean_title(title_raw)
    doi = ent.get('doi')
    url = ent.get('url')
    year = ent.get('year')
    ok=False
    method=None
    details=None
    if doi:
        ok, details = doi_resolves(doi)
        method='doi'
    if not ok and url:
        ok, details = url_ok(url)
        method = 'url' if not method else method+'+url'
    if not ok:
        ok, details = crossref_title_exists(title, year=year)
        method = (method+'+crossref') if method else 'crossref'
    results.append({'id':ent.get('ID'), 'title':title, 'doi':doi, 'url':url, 'year':year, 'ok':ok, 'method':method, 'details':details})

# print summary
for r in results:
    status = 'OK' if r['ok'] else 'FAIL'
    print(f"{status:4} | {r['id']:<25} | {r['title']}")
    if not r['ok']:
        print('    method', r['method'], 'details', r['details'])

fails=[r for r in results if not r['ok']]
print('\nFAIL COUNT', len(fails))
PY"}

